{"path": "task.py", "content": "def heap_merge(*args, **kwargs):
    import heapq
    heap = []
    for arg in args:
        try:
            it = iter(arg)
            first = next(it)
            heap.append((first, it))
        except StopIteration:
            pass
    heapq.heapify(heap)
    result = []
    while heap:
        val, it = heapq.heappop(heap)
        result.append(val)
        try:
            next_val = next(it)
            heapq.heappush(heap, (next_val, it))
        except StopIteration:
            pass
    return result"}

